  FT["PH-H5913"] = {"id":"PH-H5913","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7429_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Carmen市","en":"An Act Converting the Rural Health Unit in the Municipality of Carmen, Province of Davao Del Norte, Into A Five-bed Capacity Health Infirmary, To Be Known As the Carmen Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Carmen, Province of Davao Del Norte, Into A Five-bed Capacity Health Infirmary, To Be Known As the Carmen Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7429","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7429_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5913-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Carmen, Province of Davao del Norte, is hereby converted into a five-bed capacity health infirmary, to be known as the Carmen Health Infirmary."}},{"id":"PH-H5913-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5913-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5914"] = {"id":"PH-H5914","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7430_1992.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing For Optimum Utilization of Personnel in Government Service Through A System of Attrition, Providing Penalties For Violation Thereof, and For Other Purposes","orig":"An Act Providing For Optimum Utilization of Personnel in Government Service Through A System of Attrition, Providing Penalties For Violation Thereof, and For Other Purposes"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 7430","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-15","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7430_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5914-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy . - It is the policy of the State to give highest priority to measures that will promote morale, efficiency, integrity, responsiveness and progressiveness in the civil service. Towards this end, optimum utilization of personnel shall be assured through the institution of a system of attrition in government."}},{"id":"PH-H5914-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Definition of Terms. - As used in this Act, the following terms shall mean:\na. \"Attrition\" - The reduction of personnel as a result of resignation, retirement, dismissal in accordance with existing laws, death or transfer to another office; and\nb. \"Government\" - Includes the National Government, and all its instrumentalities or agencies including government-owned or - controlled corporations and their subsidiaries, excluding local government units."}},{"id":"PH-H5914-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Attrition - Within five (5) years from the approval of this Act, no appointment shall be made to fill vacated positions in any government office as a result of resignation, retirement, dismissal, death or transfer to another office of an officer or employee: Provided, however, That this prohibition shall not apply in the following instances:\na. Where the position is head of a primary organic unit such as chief of division;\nb. Where the position is the lone position in the organizational unit it corresponds to a particular expertise that is intrinsic to the desired basic capability of the unit concerned;\nc. Where the positions are basic positions for the initial operations of newly created or activated agencies or, in the case of other agencies, where the positions are vital and necessary for the continued and efficient operation of said agencies;\nd. Where the positions are difficult to fill considering the qualifications required therefor, as in the case of doctors, lawyers and other professionals;\ne. Where the positions are found in agencies declared to be understaffed;\nf. Positions in Congress or in the Judiciary;\ng. Appointments or designations extended by the President;\nh. Where the positions are found in local government units;\ni. Teaching personnel; and\nj. Where the replacements come from existing employees.\nProvided further, That exemptions from this prohibition shall require authorization by the Civil Service Commission: Provided, finally, That no appointment shall be issued by the appointing authority nor approved by the Civil Service Commission without said authorization.\nAppointments made in violation of this Act shall be null and void."}},{"id":"PH-H5914-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Penalty. - Any appointing authority who makes an appointment in violation of this Act shall, upon conviction, be punished by imprisonment of not less than three (3) months but not exceeding six (6) months or by a fine of not less than Three thousand pesos (3,000) but not exceeding Five thousand pesos (P5,000), or both such imprisonment and fine, at the discretion of the court.\nIn addition, the appointing official shall be personally liable for the salary that would have accrued had the employment been lawful, and the disbursing official shall make payment to the employee of such amount from the salary of the appointing authority."}},{"id":"PH-H5914-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Annual Reports. - The Civil Service Commission, as the central personnel agency of the Government, shall monitor and render an annual report to the President and the Congress on the extent of compliance with the law.\nThe report shall include, among others, the following:\na. Total number of positions authorized in the agency's annual budget;\nb. Total number of officers and employees at the end of the year;\nc. Total number of officers and employees separated from the service during the year categorized as follows:\n1. Those who resigned;\n2. Those who retired;\n3. Those who were dismissed from the service;\n4. Those who died; and\n5. Those who transferred to another agency.\nd. Total number of new personnel recruited during the year; and\ne. Total number of vacancies at the end of the year.\nThe Commission shall also conduct a personnel effectiveness audit of all government agencies to determine optimum utilization of personnel. The audit reports shall, among others, include information on whether the agency is overstaffed or understaffed and its minimum and maximum personnel requirements.\nThe Commission shall likewise conduct and prepare a work study which shall contain among others: the evaluation and effectiveness of the program during the five-year period of its enforcement and the feasibility of extending the same to another period. The Commission shall submit its audit reports and work study together with its recommendations to the President and the Congress of the Philippines."}},{"id":"PH-H5914-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Rules and Regulations. - The Civil Service Commission shall issue the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H5914-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Repealing Clause . - All laws, presidential decrees, executive orders, other executive issuances, or parts thereof, which are inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5914-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p84"};
  FT["PH-H5915"] = {"id":"PH-H5915","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7431_1992.html","fetchedAt":"2026-10-06","articleCount":29,"structureMode":"ARTICLE","title":{"zh":"放射技术执业规制法","en":"An Act Regulating the Practice of Radiologic Technology in the Philippines,Creating the Board of Radiologic Technology, Defining Its Powers and Functions and For Other Purposes","orig":"An Act Regulating the Practice of Radiologic Technology in the Philippines,Creating the Board of Radiologic Technology, Defining Its Powers and Functions and For Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7431","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-22","completenessNote":"全文，共 29 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7431_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 30 条，缺 29）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5915-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . This Act shall be known and cited as the \"Radiologic TechnoIogy Act of 1992.\""}},{"id":"PH-H5915-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Statement of Policy. - It is the policy of the State to upgrade the practice of radiologic technology in the Philippines for the purpose of protecting the public from the hazards posed by radiation as well as to ensure safe and proper diagnosis, treatment and research through the application of machines and/or equipment using radiation."}},{"id":"PH-H5915-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. - As used in this Act, the following terms shall mean:\na. \"X-ray technology\" is an auxiliary branch of radiology which deals with the technical application of x-rays as aid in the diagnosis of diseases and injuries;\nb. \"Radiologic technology\" is an auxiliary branch of radiology which deals with the technical application of radiation, such as x-rays, beta rays, gamma rays, ultra sound and radio frequency rays, in the diagnosis and treatment of diseases;\nc. \"X-ray technologist\" is a bona fide holder of a certificate of registration for x-ray technology issued by the Board of Radiologic Technology in accordance with this Act;\nd. \"Radiologic technologist\" is a bona fide holder of a certificate of registration for radiologic technology issued by the Board of Radiologic Technology in accordance with this Act;\ne. \"Radiology\" is a branch of medical science which deals with the use of radiation in the diagnosis, treatment and research of diseases;\nf. \"Radiologist\" is a licensed physician who specializes in the diagnosis or treatment of diseases with the use of radiation;\ng. \"Medical physicist\" is a physicist who specializes in the application of the principles and techniques of physics in medicine;\nh. \"Board\" refers to the Board of Radiologic Technology; and\ni. \"Commission, refers to the Professional Regulation Commission created under Presidential Decree Numbered Two hundred and twenty-three."}},{"id":"PH-H5915-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Practice of X-ray Technology. - The practice of x-ray technology shall include any and all acts by which one renders, furnishes, or contracts to render or furnish professional service as an x-ray technologist.\nAn x-ray technologist shall also be considered in the practice of his profession if the nature and character of his employment requires professional knowledge in the art and science of x-ray technology and such employment or position requires that the holder thereof be an x-ray technologist.\nNothing in this Act shall be construed to disqualify other professionals duly registered with the Professional Regulation Commission from performing any of the acts abovementioned: Provided, That under the law or laws governing their respective professions, they may perform the said acts: Provided further, That no person shall use the title \"X-ray Technologist\" or any other title conveying the impression that he is an x-ray technologist without having been issued a certificate of registration as x-ray technologist by the Commission in the manner provided in this Act."}},{"id":"PH-H5915-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Practice of Radiologic Technology. - The practice of radiologic technology shall include any and all acts by which one renders, furnishes, or contracts to render or furnish professional service as a radiologic technologist.\nA radiologic technologist shall also be considered in the practice of his profession if the nature and character of his employment requires professional knowledge in the art and science of radiologic technology, and such employment or position requires that the holder thereof be a radiologic technologist.\nNothing in this Act shall be construed to disqualify other professionals duly registered with the Professional Regulation Commission from performing any of the acts abovementioned: Provided, That under the law or laws governing their respective professions, they may perform the said acts: Provided further, That no person shall use the title \"Radiologic Technologist' or any other title conveying the impression that he is a radiologic technologist without having been issued a certificate of registration as radiologic technologist by the Commission in the manner provided in this Act."}},{"id":"PH-H5915-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Creation of the Board of Radiologic Technology. - There is hereby created a Board of Radiologic Technology which shall be composed of a Chairman and four (4) members, all of whom shall be appointed by the President of the Philippines upon recommendation of the Professional Regulation Commission. The Commission shall recommend three (3) radiologic technologists from a list to be submitted by the association of radiologic technologists; one (1) radiologist from a list to be submitted by the association of radiologists; and one (1) medical physicist from a list to be submitted by the association of medical physicists: Provided, however, That the said associations are accredited in accordance with Presidential Decree Numbered Two hundred and twenty-three: Provided, further, That each person shall possess the qualifications prescribed in Section 7 of this Act."}},{"id":"PH-H5915-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Qualifications of Board Members. -\na. Each member of the Board shall at the time of his appointment:\n1. Be a citizen and resident of the Philippines\n2. Be of good moral character;\n3. Be at least thirty (30) years of age; and\n4. Is neither a member of the faculty, whether full time, part time or lecturer, of any school, college or university where a regular course in radiologic technology is taught, nor has any pecuniary interest, directly or indirectly, in such institution during his term of office as a Board member.\nb. Three (3) members of the Board, including the Chairman, shall at the time of their appointment:\n1. Be radiologic technologists; and\n2. Have at least ten (10) years practice as radiologic technologists prior to their appointment: Provided, That the three (3) radiologic technologists appointed as members of the first Board shall be deemed automatically registered as radiologic technologists upon assumption of their duties members.\nc. One (1) member of the Board shall at the time of his appointment:\n1. Be a radiologists; and\n2. Has at least ten (10) years practice as a radiologist prior to his appointment:\nd. One (1) member of the Board shall at the time of his appointment:\n1. Be a medical physicist; and\n2. Has at least ten (10) years practice as a medical physicist."}},{"id":"PH-H5915-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Term of Office. - The members of the Board shall hold office for a term of three (3) years from the date of their appointment until their successors shall have been appointed and duly qualified: Provided, That the first appointees to the Board shall hold office for the following terms: the Chairman for three (3) years; two (2) members for two (2) years; and two (2) members for one (1) year. Vacancies shall be filled only for the unexpired term."}},{"id":"PH-H5915-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Duties and Functions of the Board. - The Board shall have the following duties and functions:\na. To enforce the provisions of this Act;\nb. To administer oaths in accordance with the provisions of this Act;\nc. To issue and, after due investigation, suspend or revoke certificates of registration for the practice of radiologic technology and x-ray technology;\nd. To investigate any violation of this Act or of the rules and regulations issued thereunder, as may come to the knowledge of the Board and, for this purpose, to issue subpoena and subpoena duces tecum to alleged violators or witnesses to secure their attendance in investigations or hearings, and the production of books, paperrs and documents in connection therewith and compel their attendance by the power to cite and punish for contempt;\ne. To conduct yearly board examinations to radiologic technology and x-ray technology examinees under the supervision of the Professional Regulation Commission;\nf. To look, from time to time, into the condition affecting the practice of radiologic technology and x-ray technology in the Philippines, and adopt such measures as may be deemed necessary for the maintenance of the standards and ethics of the profession;\ng. To promulgate such rules and regulations as may be necessary to carry out the provisions of this Act: Provided, That the same shall be issued only after the approval thereof by the Commission; and\nh. To adopt a seal to authentic its official documents.\nThe Board shall exercise these powers and duties in accordance with Presidential Decree Numbered Two hundred and twenty-three."}},{"id":"PH-H5915-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Compensation of the Board. - The members of the Board shall each receive the same compensation as members of other Boards under the supervision of the Commission as provided for in the General Appropriations Act."}},{"id":"PH-H5915-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Removal of Board Members. - Any member of the Board may be removed from office by the President upon the recommendation of the Commission for neglect of duty, incompetence or unprofessional, immoral, or dishonorable conduct, or commission or toleration of irregularities in the conduct of the examinations, after having been given the opportunity to defend himself in a proper administrative investigation conducted by the Commission."}},{"id":"PH-H5915-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Supervision of the Board and Custody of Its Records. - The members of the Board shall be under the general supervision of the Commission.\nNo record shall be removed, altered or examined without the prior authorization of the Board. All records, including examination papers, examination results, minutes of deliberation, records of administrative cases and investigations of the Board shall be kept by the Commission."}},{"id":"PH-H5915-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Rules and Regulations. - Subject to the approval of the Commission, the Board shall set ethical and professional standards for the practice of radiologic technology and x-ray technology and adopt such rules and regulations as may be necessary to carry out the provisions of this Act. Such standards, rules and regulations shall take effect one (1) month after publication in any newspaper of general circulation."}},{"id":"PH-H5915-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Annual Report. - The Board shall, at the end of each calendar year, submit to the Commission an annual report of its activities and proceedings during the year. Other information or data may be requested by the Commission as often as may be necessary and practicable."}},{"id":"PH-H5915-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Requirement for the Practice of Radiologic Technology and X-ray Technology. - Unless exempt from the examinations under Sections 16 and 17 hereof, no person shall practice or offer to practice as a radiologic technologist and/or x-ray technologist in the Philippines without having obtained the proper certificate of registration from the Board."}},{"id":"PH-H5915-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Exemption from Examination in X-ray Technology. - Examinations shall not be required of the following persons:\na. The first members of the Board of Radiologic Technology as provided in Section 7 (b) hereof; and\nb. Those who, prior to the approval of this Act, have passed the Civil Service examination for x-ray technicians, or the examination for the private sector x-ray technicians, or the examination for chest x-ray technicians, or the proficiency examination for medical radiation technicians administered by the Department of Health through its Radiation Health Office, Radiological Health Service, or Radiation Health Service.\nThose so exempt under the aforementioned categories shall register with the Board after they shall have complied with the requirements for registration as radiologic technologists."}},{"id":"PH-H5915-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Exemption from Examination in Radiologic Technology. - Examination shall not be required of the following persons:\na. The first members of the Board of Radiologic Technology as provided in Section 7(b) hereof;\nb. Radiologic technologists from other countries invited for lectures or consultation or as visiting or exchange professors to colleges or universities duly recognized by the Government: Provided, That such radiologic technologists arc legally qualified to practice as such in their own state or country: Provided, further, That they shall first secure a special from the Board which shall be valid as the Board may determine: Provided, finally, That the privilege granted in this subsection shall be given only to radiologic technologists from countries giving similar privilege to their Filipino counterparts;\nc. Those who, prior to the approval of this Act, have passed the proficiency examination for medical radiation technologists administered by the Department of Health through its Radiation Health Office, Radiological Health Service, or Radiation Health Service; and\nd. Those who, prior to the approval of this Act, have passed the Civil Service examination for x-ray technicians, or the examination for private sector x-ray technicians, or the proficiency examination for medical radiation technicians administered by the Department of Health through its Radiation Health Office, Radiological Health Service or Radiation Health Service, with ten (10) years continuous practice of radiologic technology after passing one of these aforementioned examinations.\nThose falling under categories (a), (c) and (d) shall register with the Board after they shall have complied with the requirements for registration as radiologic technologists."}},{"id":"PH-H5915-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Examination Required. - Except as otherwise specifically allowed under the provisions of this Act and other existing laws, all applicants for registration as radiologic technologists and x-ray technologists shall be required to undergo an examination which shall he given once a year by the Board, through the Commission, according to its rules and regulations and at such time and place as may be determined by the Commission."}},{"id":"PH-H5915-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Qualifications for Examination. - Every applicant for examination under this Act shall, prior to admission for examination, establish to the satisfaction of the Board that he:\na. Is a Filipino citizen;\nb. Is of good moral character and has not been convicted of a crime involving moral turpitude; and\nc. Is a holder of a baccalaureate degree in radiologic technology from a school, college or university recognized by the Government if he applies for the radiologic technology examination, or is a holder of an associate in radiologic technology diploma from a school, college or university recognized by the Government if he applies for the x-ray technology examination."}},{"id":"PH-H5915-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Scope of Examination in X-ray Technology. - Unless changed or modified by the Board, the examination in x-ray technology shall cover the following subjects with the corresponding weights as follows:\n(a) Radiation Physics 10% Radiobiology and Radiation Protection 10% Equipment Maintenance 10% (b) Radiographic Positioning 10% Radiographic Technique 10% Special Procedures 10% (c) Anatomy, Physiology and Medical Terminology 15% (d) Photochemistry and Darkroom Procedures 10% (e) Film Analysis 5% (f) Nursing and Department Procedures in Radiology 5% (g) Professional Ethics 5%"}},{"id":"PH-H5915-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Scope of Examination in Radiologic Technology. - Unless changed or modified by the Board, the examination in radiologic technology shall cover the following subjects with the corresponding weights as follows:\n(a) Radiation Physics and Equipment 10% Maintenance 10% Radiobiology and Radiation Protection 10% (b) Radiographic Positioning 10% Radiographic Technique 10% Special Procedures 10% (c) Anatomy, Physiology and Medical Terminology 10% (d) Photochemistry and Film Analysis 10% (e) Nursing and Departmental Procedures in Radiology and Professional Ethics 5% (f) Ultrasound 5% (g) Radiation Therapy 5% (h) Nuclear Medicine 5%\n(i) Radiologic PathoIogy 5% (j) Computed Tomography/Magnetic Resonance Imaging 5%"}},{"id":"PH-H5915-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Report of Ratings. - The Board shall, within one hundred twenty (120) days after the date of completion of the examination, report the rating obtained by each candidate to the Commission which shall submit such report to the President of the Philippines for approval.\nIn order to pass the examination, a candidate must obtain a weighted average of at least 75% with no rating below 60% in any subject. An examinee who obtains an average rating of 75% or higher but gets a rating below 60% in any subject shall be allowed to take a reexamination in only those subjects in which he obtained a rating below 60%. Such examination shall, as far as practicable, be taken in the next scheduled examination.\nIn order to pass the second examination, the examinee must obtain a rating of 75% in each of the subjects repeated. If the candidate still fails the reexamination, he shall, as far as practicable be required to repeat said subjects during the succeeding examination. When an applicant fails to qualify after the third examination, he shall be required to take the entire examination."}},{"id":"PH-H5915-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Oath-taking. - All successful examinees shall be required to take a professional oath before the Board or before any person authorized by the Board to administer oaths prior to the practice of their profession as radiologic technologists and/or x-ray technologists,"}},{"id":"PH-H5915-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Issuance of Certificates of Registration. - Every applicant who has satisfactorily passed the required examination shall, upon payment of the registration fee as provided in Section 25, be issued a certificate of registration as radiologic technologist and/or x-ray technologist.\nThe Board shall, subject to review by the Commission, issue the corresponding certificates to persons who apply for the same who are exempt from the examinations provided under Sections 16 and 17 thereof.\nAll certificates of registration shall contain the full name of the registrant, serial number, signature of the Commissioner, date of issuance, and the official seal of the Board duly affixed thereto."}},{"id":"PH-H5915-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Fees. - Unless otherwise fixed by the Commission, each examinee or registrant shall pay the following fees:\n(a) For application for examination P 350.00 (b) For registration after passing the board examinations P 250.00 (c) For registration without examination P 250.00 (d) For replacement of lost or destroyed certificate of registration P 100.00 (e) For re-issuance of revoked certificate P 100.00"}},{"id":"PH-H5915-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Penal Provisions. - Any person who shall practice radiologic technology and/or x-ray technology in the Philippines, within the meaning of this Act, with any of the following attending circumstances shall, upon conviction by final judgment, be punished with a fine of not less than Ten thousand pesos (P 10,000) nor more than Forty thousand pesos (P40,000), or by imprisonment of not less than one (1) year nor more than six (6) years, or both, at the discretion of the court:\na. Without a certificate of registration in accordance with the provisions of this Act;\nb. Presenting or using as his own the certificate of registration of another person;\nc. Using an expired license, or suspended or revoked certificate of registration;\nd. Giving any false or forged evidence to the Board of Radiologic Technology in order to obtain a certificate of registration;\ne. Posing or advertising as a registered radiologic and/or x-ray technologist or using any other means tending to convey the impression that he is a registered radiologic and/or x-ray technologist; and\nf. Violation of any of the provision or provisions of this Act."}},{"id":"PH-H5915-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Appropriations. - The amount necessary for the compensation of the members of the Board shall be included in the General Appropriations Act of the year following the approval of this Act and thereafter."}},{"id":"PH-H5915-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Repealing Clause . - All laws, decrees, orders, and other issuances, rules and regulations, or parts thereof, inconsistent herewith are hereby repealed or modified accordingly."}},{"id":"PH-H5915-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Effectivity Clause. - This Act shall take effect one (1) month after its publication in any newspaper of general circulation."}}],"pack":"ph-p84"};
  FT["PH-H5916"] = {"id":"PH-H5916","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7432_1992.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act To Maximize the Contribution of Senior Citizens To Nation Building, Grant Benefits and Special Privileges and For Other Purposes.","orig":"An Act To Maximize the Contribution of Senior Citizens To Nation Building, Grant Benefits and Special Privileges and For Other Purposes."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7432","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-23","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7432_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5916-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policies and Objectives. — Pursuant to Article XV, Section 4 of the Constitution, it is the duty of the family to take care of its elderly members while the State may design programs of social security for them. In addition to his, Section 10 in the Declaration of Principles and State Policies provides: \"The State shall provide social justice in all phases of national development.\" Further, Article XIII, Section 11 provides: \"The State shall adopt an integrated and comprehensive approach to health development which shall endeavor to make essential goods, health and other social services available to all the people at affordable cost. There shall be priority for the needs of the underprivileged, sick, elderly, disabled, women and children.\" Consonant with these constitutional principles the following are the declared policies of this Act:\na. to motivate and encourage the senior citizens to contribute to nation building;\nb. to encourage their families and the communities they live with to reaffirm the valued Filipino tradition of caring for the senior citizens.\nIn accordance with those policies, this Act aims to:\n1. establish mechanisms whereby the contribution of the senior citizens are maximized;\n2. adopt measures whereby our senior citizens are assisted and appreciated by the community as a whole;\n3. establish a program beneficial to the senior citizens, their families and the rest of the community that they serve."}},{"id":"PH-H5916-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Definition of Terms. — As used in this Act, the term \"senior citizen\" shall mean any resident citizen of the Philippines at least sixty (60) years old, including those who have retired from both government offices and private enterprises, and has an income of not more than Sixty thousand pesos (P60,000.00) per annum subject to review by the National Economic and Development Authority (NEDA) every three (3) years.\nThe term \"benefactor\" shall mean any person whether related to the senior citizens or not who takes care of him/her as a dependent.\nThe term \"head of the family\" shall mean any person so defined in the National Internal Revenue Code."}},{"id":"PH-H5916-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Contribution to the Community. — Any qualified senior citizen as determined by the Office for Senior Citizen Affairs (OSCA) may render his/her services to the community which shall consist of, but not limited to, any of the following:\na. tutorial and/or consultancy services;\nb. actual teaching and demonstration of hobbies and income generating skills;\nc. lectures on specialized fields like agriculture, health, environmental protection and the like;\nd. the transfer of new skills acquired by virtue of their training mentioned in Section 4, paragraph d;\ne. undertaking other appropriate services as determined by the Office of Senior Citizens Affairs (OSCA) such as school traffic guide, tourist aid, pre-school assistant, etc.\nIn consideration of the services rendered by the qualified elderly, the Office for Senior Citizens Affairs (OSCA) may award or grant benefits or privileges to the elderly, in addition to the other privileges provided for under Section 4 hereof."}},{"id":"PH-H5916-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Privileges for the Senior Citizens. — The senior citizens shall be entitled to the following:\na. the grant of twenty percent (20%) discount from all establishments relative to utilization of transportation services, hotels and similar lodging establishment, restaurants and recreation centers and purchase of medicine anywhere in the country: Provided, That private establishments may claim the cost as tax credit;\nb. a minimum of twenty percent (20%) discount on admission fees charged by theaters, cinema houses and concert halls, circuses, carnivals and other similar places of culture, leisure, and amusement;\nc. exemption from the payment of individual income taxes: Provided, That their annual taxable income does not exceed the property level as determined by the National Economic and Development Authority (NEDA) for that year;\nd. exemption form training fees for socioeconomic programs undertaken by the OSCA as part of its work;\ne. free medical and dental services in government establishment anywhere in the country, subject to guidelines to be issued by the Department of Health, the Government Service Insurance System and the Social Security System;\nf. to the extent practicable and feasible, the continuance of the same benefits and privileges given by the Government Service Insurance System (GSIS), Social Security System (SSS) and PAG-IBIG, as the case may be, as are enjoyed by those in actual service."}},{"id":"PH-H5916-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Government Assistance. — The Government shall provide the following assistance to those caring for and living with the senior citizen:\na. The senior shall be treated as dependents provided for in the National Internal Revenue Code and as such, individual taxpayers caring for them, be they relatives or not shall be accorded the privileges granted by the Code insofar as having dependents are concerned.\nb. Individuals or non-governmental institutions establishing homes, residential communities or retirement villages solely for the senior citizens shall be accorded the following:\n1. realty tax holiday for the first five (5) years starting from the first year of operation;\n2. priority in the building and/or maintenance of provincial or municipal roads leading to the aforesaid home, residential community or retirement village."}},{"id":"PH-H5916-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Retirement Benefits. — To the extent practicable and feasible, retirement benefits from both the Government and the private sectors shall be upgraded to be at par with the current scale enjoyed by those in actual service."}},{"id":"PH-H5916-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Office for Senior Citizens Affairs (OSCA). — There shall be established in the Office of the Mayor an OSCA to be headed by a Councilor who shall be designated by the Sangguniang Bayan and assisted by the Community Development Officer in coordination with the Department of Social Welfare and Development. The functions of this office are:\na. to plan, implement and monitor yearly work programs in pursuance of the objectives of this Act;\nb. to draw up a list of available and required services which can be provided by the senior citizens;\nc. to maintain and regularly update on a quarterly basis the list of senior citizens and to issue nationally uniform individual identification cards which shall be valid anywhere in the country;\nd. to service as a general information and liaison center to serve the needs of the senior citizens."}},{"id":"PH-H5916-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Municipality Responsibility. — It shall be the responsibility of the municipality through the mayor to ensure that the provisions of this Act are implemented to its fullest."}},{"id":"PH-H5916-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Penalties. — Violation of any provision of this Act for which no penalty is specifically provided under any other law, shall be punished by imprisonment not exceeding one (1) month or a fine not exceeding One thousand pesos (P1,000.00) or both."}},{"id":"PH-H5916-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Implementing Rules and Regulations . — The Secretary of Social Welfare and Development, jointly with the Department of Finance, the Department of Tourism, the Department of Health, the Department of Transportation and Communications and the Department of Interior and Local Government shall issue the necessary rules and regulations to carry out the objectives of this Act."}},{"id":"PH-H5916-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Appropriation. — The necessary appropriation for the operation and maintenance of the OSCA shall be appropriated and approved by the local government units concerned. The National Government shall appropriate such amount, as may be necessary to carry out the objectives of this Act."}},{"id":"PH-H5916-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Repealing Clause . — All provisions of laws, orders, decrees, including rules and regulations inconsistent herewith are hereby repealed and/or modified accordingly."}},{"id":"PH-H5916-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause . — If any part or provision of this Act shall be held to be unconstitutional or invalid, other provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H5916-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effectivity . — This Act shall take effect fifteen (15) days following its publication in one (1) national newspaper of general circulation."}}],"pack":"ph-p84"};
  FT["PH-H5917"] = {"id":"PH-H5917","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7433_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Surigao Del Sur Provincial Hospital in the Municipality of Tandag, Province of Surigao Del Sur, To Adela Serra Ty Memorial Hospital","orig":"An Act Changing the Name of the Surigao Del Sur Provincial Hospital in the Municipality of Tandag, Province of Surigao Del Sur, To Adela Serra Ty Memorial Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7433","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7433_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5917-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Surigao del Sur Provincial Hospital in the Municipality of Tandag, Province of Surigao del Sur, is hereby changed to Adela Serra Ty Memorial Hospital."}},{"id":"PH-H5917-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5918"] = {"id":"PH-H5918","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7434_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Doña Maria D. Tan Memorial Hospital in the City of Tangub, Province of Misamis Occidental, To Ninoy Aquino Memorial Hospital","orig":"An Act Changing the Name of the Doña Maria D. Tan Memorial Hospital in the City of Tangub, Province of Misamis Occidental, To Ninoy Aquino Memorial Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7434","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7434_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5918-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Doña Maria D. Tan Memorial Hospital in Tangub City, Province of Misamis Occidental, is hereby changed to Ninoy Aquino Memorial Hospital."}},{"id":"PH-H5918-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 23, 1992"}}],"pack":"ph-p84"};
  FT["PH-H5919"] = {"id":"PH-H5919","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7435_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Naming the Jagna District Hospital As the Teodoro B. Galagar District Hospital","orig":"An Act Naming the Jagna District Hospital As the Teodoro B. Galagar District Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7435","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7435_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5919-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Jagna District Hospital is hereby named as Teodoro B. Galagar District Hospital."}},{"id":"PH-H5919-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 23, 1992"}}],"pack":"ph-p84"};
  FT["PH-H5920"] = {"id":"PH-H5920","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7436_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Expanding and Upgrading the Aurora Memorial Hospital in the Municipality of Baler, Province of Aurora, From A Twenty-five-bed Capacity District Hospital Into A One Hundred-bed Capacity Provincial Hospital, To Be Known As the Aurora Provincial Hospital, and Appropriating Funds Therefor","orig":"An Act Expanding and Upgrading the Aurora Memorial Hospital in the Municipality of Baler, Province of Aurora, From A Twenty-five-bed Capacity District Hospital Into A One Hundred-bed Capacity Provincial Hospital, To Be Known As the Aurora Provincial Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7436","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7436_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5920-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Aurora Memorial Hospital in the Municipality of Baler, Province of Aurora, is hereby expanded and upgraded from a twenty-five bed capacity district hospital into a one hundred-bed capacity provincial hospital, to be known as the Aurora Provincial Hospital."}},{"id":"PH-H5920-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5920-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5921"] = {"id":"PH-H5921","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7437_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Expanding and Upgrading the Lakewood Municipal Hospital in the Municipality of Lakewood, Province of Zamboanga Del Sur, From A Ten-bed Capacity Municipal Hospital Into A Twenty-five-bed Capacity District Hospital, To Be Known As the Lakewood District Hospital, and Appropriating Funds Therefor","orig":"An Act Expanding and Upgrading the Lakewood Municipal Hospital in the Municipality of Lakewood, Province of Zamboanga Del Sur, From A Ten-bed Capacity Municipal Hospital Into A Twenty-five-bed Capacity District Hospital, To Be Known As the Lakewood District Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7437","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7437_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5921-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Lakewood Municipal Hospital in the Municipality of Lakewood, Province of Zamboanga del Sur, is hereby expanded and upgraded from a ten-bed capacity municipal hospital into a twenty-five bed capacity district hospital, to be known as the Lakewood District Hospital."}},{"id":"PH-H5921-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5921-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5922"] = {"id":"PH-H5922","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7438_1992.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Defining Certain Rights of Person Arrested, Detained or Under Custodial Investigation as Well as the Duties of the Arresting, Detaining and Investigating officers, and Providing Penalties for Violations thereof","orig":"An Act Defining Certain Rights of Person Arrested, Detained or Under Custodial Investigation as Well as the Duties of the Arresting, Detaining and Investigating officers, and Providing Penalties for Violations thereof"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 7438","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7438_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5922-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Statement of Policy. – It is the policy of the Senate to value the dignity of every human being and guarantee full respect for human rights."}},{"id":"PH-H5922-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Rights of Persons Arrested, Detained or Under Custodial Investigation; Duties of Public Officers. –\n(a) Any person arrested detained or under custodial investigation shall at all times be assisted by counsel.\n(b) Any public officer or employee, or anyone acting under his order or his place, who arrests, detains or investigates any person for the commission of an offense shall inform the latter, in a language known to and understood by him, of his rights to remain silent and to have competent and independent counsel, preferably of his own choice, who shall at all times be allowed to confer privately with the person arrested, detained or under custodial investigation. If such person cannot afford the services of his own counsel, he must be provided with a competent and independent counsel by the investigating officer.\n(c) The custodial investigation report shall be reduced to writing by the investigating officer, provided that before such report is signed, or thumbmarked if the person arrested or detained does not know how to read and write, it shall be read and adequately explained to him by his counsel or by the assisting counsel provided by the investigating officer in the language or dialect known to such arrested or detained person, otherwise, such investigation report shall be null and void and of no effect whatsoever.\n(d) Any extrajudicial confession made by a person arrested, detained or under custodial investigation shall be in writing and signed by such person in the presence of his counsel or in the latter's absence, upon a valid waiver, and in the presence of any of the parents, elder brothers and sisters, his spouse, the municipal mayor, the municipal judge, district school supervisor, or priest or minister of the gospel as chosen by him; otherwise, such extrajudicial confession shall be inadmissible as evidence in any proceeding.\n(e) Any waiver by a person arrested or detained under the provisions of Article 125 of the Revised Penal Code, or under custodial investigation, shall be in writing and signed by such person in the presence of his counsel; otherwise the waiver shall be null and void and of no effect.\n(f) Any person arrested or detained or under custodial investigation shall be allowed visits by or conferences with any member of his immediate family, or any medical doctor or priest or religious minister chosen by him or by any member of his immediate family or by his counsel, or by any national non-governmental organization duly accredited by the Commission on Human Rights of by any international non-governmental organization duly accredited by the Office of the President. The person's \"immediate family\" shall include his or her spouse, fiancé or fiancée, parent or child, brother or sister, grandparent or grandchild, uncle or aunt, nephew or niece, and guardian or ward.\nAs used in this Act, \"custodial investigation\" shall include the practice of issuing an \"invitation\" to a person who is investigated in connection with an offense he is suspected to have committed, without prejudice to the liability of the \"inviting\" officer for any violation of law."}},{"id":"PH-H5922-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Assisting Counsel. – Assisting counsel is any lawyer, except those directly affected by the case, those charged with conducting preliminary investigation or those charged with the prosecution of crimes.\nThe assisting counsel other than the government lawyers shall be entitled to the following fees;\n(a) The amount of One hundred fifty pesos (P150.00) if the suspected person is chargeable with light felonies;\n(b) The amount of Two hundred fifty pesos (P250.00) if the suspected person is chargeable with less grave or grave felonies;\n(c) The amount of Three hundred fifty pesos (P350.00) if the suspected person is chargeable with a capital offense.\nThe fee for the assisting counsel shall be paid by the city or municipality where the custodial investigation is conducted, provided that if the municipality of city cannot pay such fee, the province comprising such municipality or city shall pay the fee: Provided, That the Municipal or City Treasurer must certify that no funds are available to pay the fees of assisting counsel before the province pays said fees.\nIn the absence of any lawyer, no custodial investigation shall be conducted and the suspected person can only be detained by the investigating officer in accordance with the provisions of Article 125 of the Revised Penal Code."}},{"id":"PH-H5922-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Penalty Clause. – (a) Any arresting public officer or employee, or any investigating officer, who fails to inform any person arrested, detained or under custodial investigation of his right to remain silent and to have competent and independent counsel preferably of his own choice, shall suffer a fine of Six thousand pesos (P6,000.00) or a penalty of imprisonment of not less than eight (8) years but not more than ten (10) years, or both. The penalty of perpetual absolute disqualification shall also be imposed upon the investigating officer who has been previously convicted of a similar offense.\nThe same penalties shall be imposed upon a public officer or employee, or anyone acting upon orders of such investigating officer or in his place, who fails to provide a competent and independent counsel to a person arrested, detained or under custodial investigation for the commission of an offense if the latter cannot afford the services of his own counsel.\n(b) Any person who obstructs, prevents or prohibits any lawyer, any member of the immediate family of a person arrested, detained or under custodial investigation, or any medical doctor or priest or religious minister chosen by him or by any member of his immediate family or by his counsel, from visiting and conferring privately with him, or from examining and treating him, or from ministering to his spiritual needs, at any hour of the day or, in urgent cases, of the night shall suffer the penalty of imprisonment of not less than four (4) years nor more than six (6) years, and a fine of four thousand pesos (P4,000.00).\nThe provisions of the above Section notwithstanding, any security officer with custodial responsibility over any detainee or prisoner may undertake such reasonable measures as may be necessary to secure his safety and prevent his escape."}},{"id":"PH-H5922-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Repealing Clause. – Republic Act No. No. 857, as amended, is hereby repealed. Other laws, presidential decrees, executive orders or rules and regulations, or parts thereof inconsistent with the provisions of this Act are repealed or modified accordingly."}},{"id":"PH-H5922-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days following its publication in the Official Gazette or in any daily newspapers of general circulation in the Philippines."}}],"pack":"ph-p84"};
  FT["PH-H5923"] = {"id":"PH-H5923","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7439_1992.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Authorizing A Partial Increase in the Quota Allocation For Promotion To the Grade of Major/Lieutenant Commander (PN) in the Armed Forces of the Philippines in Order To Avoid Unreasonable Delay in the Promotion of the Officers in the Grade of Captain/Lieutenant (PN)","orig":"An Act Authorizing A Partial Increase in the Quota Allocation For Promotion To the Grade of Major/Lieutenant Commander (PN) in the Armed Forces of the Philippines in Order To Avoid Unreasonable Delay in the Promotion of the Officers in the Grade of Captain/Lieutenant (PN)"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 7439","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7439_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5923-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Whenever the number of officers in the grade of Captain/Lieutenant (PN) in the Armed Forces of the Philippines exceeds at least ten percent (10%) of the number authorized by existing law, the President, upon the recommendation of the Secretary of National Defense, may declare as additional promotional vacancies to the grade of Major/Lieutenant Commander (PN) a number not to exceed thirty-three percent (33%) of the excess number of officers in the said grade of Captain/Lieutenant (PN)."}},{"id":"PH-H5923-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The selection of officers in the grade of Captain/Lieutenant (PN) who will be promoted to the next higher grade and occupy the additional promotional vacancies under this Act shall be made in accordance with the provisions of existing laws on promotions to the grade of Major/Lieutenant Commander (PN)."}},{"id":"PH-H5923-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to implement the provisions of this Act is hereby authorized to be sourced out of the savings from the appropriations of the Armed Forces for the current year. Thereafter, the sums necessary for the implementation of this Act shall be included in the annual request for appropriations of the Armed Forces in the general appropriations bill to be submitted to Congress."}},{"id":"PH-H5923-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The President, upon the recommendation of the Secretary of National Defense, shall prescribe the rules and regulations necessary for the effective implementation of this Act. Such rules and regulations shall take effect after fifteen (15) days following its publication in the Official Gazette or in a major daily newspaper of general circulation, whichever is earlier."}},{"id":"PH-H5923-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All laws, decrees, orders, rules or regulations or parts thereof inconsistent with the provisions of this Act are hereby suspended until June 30, 1994."}},{"id":"PH-H5923-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect after fifteen (15) days following its publication in the Official Gazette or in a major daily newspaper of general circulation, whichever is earlier, and shall cease to have any effect after June 30, 1994."}}],"pack":"ph-p84"};
  FT["PH-H5924"] = {"id":"PH-H5924","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7440_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Auttiorizing the Leyte State School of Arts and Trade in Tanauan, Leyte, To Offer the Courses Leading To the Degrees of Bachelor of Science in Civil Engineering, Mechanical Engineering and Electrical Engineering","orig":"An Act Auttiorizing the Leyte State School of Arts and Trade in Tanauan, Leyte, To Offer the Courses Leading To the Degrees of Bachelor of Science in Civil Engineering, Mechanical Engineering and Electrical Engineering"},"level":"law","status":"active","topics":["trade","education","culture"],"docNumber":"Republic Act No. 7440","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7440_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5924-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Leyte State School of Arts and Trade in the Municipality of Tanauan, Leyte, is hereby authorized to offer the courses leading to the degrees of Bachelor of Science in Civil Engineering, Mechanical Engineering and Electrical Engineering."}},{"id":"PH-H5924-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5924-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5925"] = {"id":"PH-H5925","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7441_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Authorizing the Leyte State School of Agriculture in Alangalang, Leyte, To Offer the Bachelor of Science in Agriculture and Bachelor of Science in Agri-business and Other Agriculture-related Programs","orig":"An Act Authorizing the Leyte State School of Agriculture in Alangalang, Leyte, To Offer the Bachelor of Science in Agriculture and Bachelor of Science in Agri-business and Other Agriculture-related Programs"},"level":"law","status":"active","topics":["education","environment","culture"],"docNumber":"Republic Act No. 7441","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7441_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5925-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Leyte State School of Agriculture in Alangalang, Leyte, is hereby authorized to offer the Bachelor of Science in Agriculture and Bachelor of Science in Agri-business and other agriculture-related programs."}},{"id":"PH-H5925-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5926"] = {"id":"PH-H5926","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7442_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity of the Sara District Hospital in the Municipality of Sara, Province of Iloilo, To 100 Beds and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Sara District Hospital in the Municipality of Sara, Province of Iloilo, To 100 Beds and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7442","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7442_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 3 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5926-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Sara District Hospital in the Municipality of Sara, Province of Iloilo, is hereby converted into a one hundred (100) - bed district hospital, to be known as the Sara District Hospital."}},{"id":"PH-H5926-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall determine the manner by which said hospital shall be operational."}},{"id":"PH-H5926-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5926-A3_2","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5927"] = {"id":"PH-H5927","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7443_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity of the Alfonso Ponce Enrile Memorial District Hospital in the Municipality of Gonzaga, Province of Cagayan, From Twenty-five (25) To Fifty (50) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Alfonso Ponce Enrile Memorial District Hospital in the Municipality of Gonzaga, Province of Cagayan, From Twenty-five (25) To Fifty (50) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7443","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7443_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5927-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Alfonso Ponce Enrile Memorial District Hospital in the Municipality of Gonzaga, Province of Cagayan, is hereby increased from twenty-five (25) to fifty (50) beds."}},{"id":"PH-H5927-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5927-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
