  FT["PH-H5929"] = {"id":"PH-H5929","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7445_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity of the Congressman Luis Hora Memorial Hospital in Mountain Province, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Congressman Luis Hora Memorial Hospital in Mountain Province, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7445","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7445_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5929-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Congressman Luis Hora Memorial Hospital in Mountain Province is hereby increased from seventy-five (75) to one hundred (100) beds."}},{"id":"PH-H5929-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5929-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5930"] = {"id":"PH-H5930","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7446_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Seventy-five-bed Capacity of the Baliuag District Hospital in Baliuag, Bulacan To One Hundred (100) To Accommodate More Patients Who Are Seeking Treatment in Said Hospital","orig":"An Act Increasing the Seventy-five-bed Capacity of the Baliuag District Hospital in Baliuag, Bulacan To One Hundred (100) To Accommodate More Patients Who Are Seeking Treatment in Said Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7446","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7446_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5930-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established an additional twenty-five-bed capacity of the Baliuag District Hospital in the town of Baliuag, Bulacan."}},{"id":"PH-H5930-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Approproations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5930-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5931"] = {"id":"PH-H5931","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7447_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity of the District Hospital of the Municipality of Bongabon, Province of Nueva Ecija, From Twenty-five (25) To Fifty (50) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the District Hospital of the Municipality of Bongabon, Province of Nueva Ecija, From Twenty-five (25) To Fifty (50) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7447","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7447_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5931-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing bed capacity of the district hospital of the Municipality of Bongabon, Province of Nueva Ecija, is hereby increased from twenty-five (25) to fifty (50) beds."}},{"id":"PH-H5931-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5931-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5932"] = {"id":"PH-H5932","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7448_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring November Four A Special Nonworking Holiday in the Province of Bohol, Designating November Two To Six As Carlos P. Garcia Week in Said Province","orig":"An Act Declaring November Four A Special Nonworking Holiday in the Province of Bohol, Designating November Two To Six As Carlos P. Garcia Week in Said Province"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7448","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7448_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5932-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"To commemorate the birth anniversary of the late President Carlos P. Garcia, November Four of every year is hereby declared as a special nonworking holiday in the Province of Bohol, and November Two to Six designated as Carlos P. Garcia Week in said province."}},{"id":"PH-H5932-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p84"};
  FT["PH-H5933"] = {"id":"PH-H5933","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7449_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring August Thirty A Special Nonworking Holiday in the Province of Bulacan","orig":"An Act Declaring August Thirty A Special Nonworking Holiday in the Province of Bulacan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7449","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7449_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5933-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"August Thirty of every year is hereby declared a special nonworking holiday in the Province of Bulacan to commemorate the birth anniversary of Marcelo H. del Pilar."}},{"id":"PH-H5933-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p84"};
  FT["PH-H5934"] = {"id":"PH-H5934","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7450_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Sta市","en":"An Act Converting the Rural Health Unit in the Municipality of Sta. Elena, Province of Camarines Norte, Into A Five-bed Capacity Health Infirmary, To Be Known As the Sta. Elena Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Sta. Elena, Province of Camarines Norte, Into A Five-bed Capacity Health Infirmary, To Be Known As the Sta. Elena Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7450","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7450_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5934-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Sta. Elena, Province of Camarines Norte, is hereby converted into a five-bed capacity health infirmary, to be known as the Sta. Elena Health Infirmary."}},{"id":"PH-H5934-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5934-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
