  FT["PH-H5936"] = {"id":"PH-H5936","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7452_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting the Nearest Rural Health Unit Along the Boundary of the Municipality of Alfonso and the Municipality of Mendez, Province of Cavite, Into A Five-bed Capacity Health Infirmary, To Be Known As the Alfonso-mendez Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Nearest Rural Health Unit Along the Boundary of the Municipality of Alfonso and the Municipality of Mendez, Province of Cavite, Into A Five-bed Capacity Health Infirmary, To Be Known As the Alfonso-mendez Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7452","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7452_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5936-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The nearest rural health unit along the boundary of the Municipality of Alfonso and the Municipality of Mendez, Province of Cavite, is hereby converted into a five-bed capacity health infirmary, to be known as the Alfonso-Mendez Health Infirmary."}},{"id":"PH-H5936-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5936-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5937"] = {"id":"PH-H5937","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7453_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Talisay市","en":"An Act Converting the Rural Health Unit 11 in the Municipality of Talisay, Province of Cebu, Into A Five-bed Capacity Health Infirmary, To Be Known As the Talisay Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit 11 in the Municipality of Talisay, Province of Cebu, Into A Five-bed Capacity Health Infirmary, To Be Known As the Talisay Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7453","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7453_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5937-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit II in the Municipality of Talisay, Province of Cebu, is hereby converted into a five-bed capacity health infirmary, to be known as the Talisay Health Infirmary."}},{"id":"PH-H5937-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5937-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5938"] = {"id":"PH-H5938","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7454_1992.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting the Camarines Sur Provincial Hospital Into the Bicol Regional Training and Teaching Hospital, Defining Its Functions, Responsibilities, Powers and Authority, and Appropriating Funds Therefor","orig":"An Act Converting the Camarines Sur Provincial Hospital Into the Bicol Regional Training and Teaching Hospital, Defining Its Functions, Responsibilities, Powers and Authority, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7454","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7454_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5938-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Camarines Sur Provincial Hospital in Naga City is hereby converted and its name changed to Bicol Regional Training and Teaching Hospital, hereafter referred to as the Hospital."}},{"id":"PH-H5938-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Coverage . - All patients requiring hospitalization and/or for special medical services coming from the different provinces and cities of the Bicol Region, who cannot be given such adequate services in their local hospitals, shall be referred by the latter to, and attended by, the Hospital. It shall continue its teaching/training and research programs and admit interns as its facilities may permit."}},{"id":"PH-H5938-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Capacity. - The Bicol Regional Training and Teaching Hospital is hereby authorized to operate on its present 450-bed capacity which includes the 200-bed Don Susano J. Rodriguez Memorial Mental Hospital at Cadlan, Pili, Camarines Sur, which is under its jurisdiction, supervision and control. Any increase in the bed capacity shall be made as demanded by the exigencies of the services upon prior approval thereof by the Secretary of Health."}},{"id":"PH-H5938-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Patient's Category. - Patients who can afford to pay as determined by the Hospital authority shall be required to pay the cost of hospitalization and/or medical treatment extended to them. Indigents shall not be required to pay the cost of hospitalization and/or medical services rendered: Provided, That a certificate of indigency issued by the barangay captain at his place of residence is submitted."}},{"id":"PH-H5938-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Donation /Grant. - The Regional Director upon prior authority of the Secretary of Health may negotiate and/or accept donations or grants from any person, natural or juridical, domestic or foreign, for the use of the Hospital for the improvement of or addition to its facilities geared at modernization."}},{"id":"PH-H5938-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Fund - The current appropriations of the Camarines Sur Provincial Hospital, its assets, real and personal, and its outstanding liabilities, are hereby transferred to, and shall be absorbed by, the Hospital. Donations/grants in transit intended for the Camarines Sur Provincial Hospital shall be credited to, and received by, the Hospital as its own.\nThe amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5938-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Repealing Clause . - All acts, executive orders, proclamations, decrees, or parts thereof inconsistent herewith are hereby repealed or modified accordingly."}},{"id":"PH-H5938-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Effectivity Clause. - This Act shall take effect immediately upon its approval."}}],"pack":"ph-p84"};
