  FT["PH-H5941"] = {"id":"PH-H5941","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7457_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Tagbina市","en":"An Act Converting the Rural Health Unit in the Municipality of Tagbina, Province of Surigao Del Sur, Into A Five-bed Capacity Health Infirmary, To Be Known As the Tagbina Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Tagbina, Province of Surigao Del Sur, Into A Five-bed Capacity Health Infirmary, To Be Known As the Tagbina Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7457","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7457_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5941-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Tagbina, Province of Surigao del Sur, is hereby converted into a five-bed capacity health infirmary, to be known as the Tagbina Health Infirmary."}},{"id":"PH-H5941-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5941-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
