  FT["PH-H5947"] = {"id":"PH-H5947","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7463_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Quezon National School of Arts and Trades in the Municipality of Mauban, Province of Quezon, To Manuel S. Enverga Memorial College of Arts and Trades","orig":"An Act Changing the Name of the Quezon National School of Arts and Trades in the Municipality of Mauban, Province of Quezon, To Manuel S. Enverga Memorial College of Arts and Trades"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 7463","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-28","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7463_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5947-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Quezon National School of Arts and Trades in the Municipality of Mauban, Province of Quezon, is hereby changed to Manuel S. Enverge Memorial College of Arts and Trades to honor and perpetuate the memory of the best known and most accomplished congressman produced by the province."}},{"id":"PH-H5947-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5948"] = {"id":"PH-H5948","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7464_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Alugan School of Craftsmanship and Home Industries in Barangay Alugan, Municipality of San Policarpo, Province of Eastern Samar, To Alugan National School of Craftsmanship and Home Industries","orig":"An Act Changing the Name of the Alugan School of Craftsmanship and Home Industries in Barangay Alugan, Municipality of San Policarpo, Province of Eastern Samar, To Alugan National School of Craftsmanship and Home Industries"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7464","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-28","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7464_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5948-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Alugan School of Craftsmanship and Home Industries in Barangay Alugan, Municipality of San Policarpo, Province of Eastern Samar, is hereby changed to Alugan National School of Craftsmanship and Home Industries."}},{"id":"PH-H5948-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
