  FT["PH-H5951"] = {"id":"PH-H5951","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7467_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Salcedo Municipal High School in the Municipality of Salcedo, Province of Eastern Samar, to Salcedo High School","orig":"An Act Changing the Name of the Salcedo Municipal High School in the Municipality of Salcedo, Province of Eastern Samar, to Salcedo High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7467","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-28","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7467_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5951-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Salcedo Municipal High School in the Municipality of Salcedo, Province of Samar, is hereby changed to Salcedo High School."}},{"id":"PH-H5951-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, April 28, 1992."}}],"pack":"ph-p84"};
  FT["PH-H5952"] = {"id":"PH-H5952","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7468_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Dibuluan Elementary School in the Municipality of Jones, Province of Isabela, To Jones East Central School","orig":"An Act Changing the Name of the Dibuluan Elementary School in the Municipality of Jones, Province of Isabela, To Jones East Central School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7468","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-28","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7468_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5952-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Dibuluan Elementary School in the Municipality of Jones, Province of Isabela, is hereby changed to Jones East Central School."}},{"id":"PH-H5952-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5953"] = {"id":"PH-H5953","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7469_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Tupol Oeste Primary School in Barangay Tupol Oeste, Municipality of Cabatuan, Province of Iloilo, To Julian B. Pueyo Primary School","orig":"An Act Changing the Name of the Tupol Oeste Primary School in Barangay Tupol Oeste, Municipality of Cabatuan, Province of Iloilo, To Julian B. Pueyo Primary School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7469","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-28","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7469_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5953-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Tupol Oeste Primary SchooI in Barangay Tupol 0este, Municipality of Cabatuan, Province of Iloilo, is hereby changed to Julian B. Pueyo Primary School."}},{"id":"PH-H5953-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5954"] = {"id":"PH-H5954","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7470_1992.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Establishing the National Economic Research and Business Assistance Center of the Philippines, Appropriating Funds Therefor, and for Other Purposes","orig":"An Act Establishing the National Economic Research and Business Assistance Center of the Philippines, Appropriating Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7470","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-29","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7470_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5954-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . - This Act shall be known as the \"National Economic Research and Business Assistance Center of the Philippines Act of 1992.\""}},{"id":"PH-H5954-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy . - It is the policy of the State to enhance economic growth by providing necessary and strategic economic and business information and research assistance thereby expediting the process of business formation and encouraging the growth of entrepreneurship in the country."}},{"id":"PH-H5954-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Creation. - There is hereby created the National Economic Research and Business and Assistance Center (NERBAC) of the Philippines, hereinafter referred to as the Center, which shall be placed under the Department of Trade and Industry."}},{"id":"PH-H5954-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Purpose. - The Center shall provide prospective entrepreneurs/investors with the basic information on various business option that are open to them in accordance with the investment priorities of the Government. The Center shall likewise provide a one-stop action center which shall facilitate the processing and documentation of all paper requirements necessary for the establishment of a business enterprise in the country, including credit services."}},{"id":"PH-H5954-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Function. - The Center shall perform the following:\na. To provide information to prospective investors, both local and foreign, on the different kinds of business opportunities that are in accord with set investment priorities of the Government;\nb. To establish an updated data bank of all industries and business enterprises in the country;\nc. To prepare pre-feasibility studies of existing as well as possible industries in the Philippines that can help entrepreneurs decide on what business to venture into;\nd. To organize and maintain a centralized one-stop shop services or assistance center that shall expedite the processing of all government requirements necessary in establishing a business;\ne. To monitor technological advances relevant to business and economy, and disseminate such information to Filipino entrepreneurs and the public in general;\nf. To formulate and coordinate the conduct of relevant research projects to help attain the Center's goals;\ng. To monitor and collate economic, technical, and industry research output of all government agencies that has reference to business enterprises, as well as to investors in the country;\nh. To collect and facilitate the gathering of information on the kind of technology/machinery needed, their prices, specifications, and where they can be purchased or leased, as well as to help rehabilitate and modernize existing machinery and equipment of essential industries; and\ni. To facilitate the gathering of information on how to harness indigenous resources and technology required for our development efforts."}},{"id":"PH-H5954-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Structural Organization. - The Center shall have a Board of Governors under which shall be the Office of the Director General and the Office of the Deputy Director General. Under the Office of the Director General shall be two (2) departments which shall be headed by the their respective directors, namely on: Agriculture, Fishery and Forestry, to handle all agricultural, agri-based, agribusiness, marine and aquaculture, and forestry matters; and Industry, Utilities and Services, to handle all industrial, utilities and service-related matters. Under each department shall be three (3) divisions which shall be headed by their division chiefs, namely on: Technical Research Assistance, to handle production and related matters; Pre-feasibility Studies Assistance, to handle all pre-feasibility studies and related matters; and Trade and Marketing Assistance, to handle market research and related matters, both for domestic and international: Provided, That a central documentation and information service headed by a director, to handle all documentation, information and related matters, including public relations, shall be constituted to provide staff support to the Director General."}},{"id":"PH-H5954-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Board of Governors. - The Board of Governors shall have the following powers and functions;\na. To formulate policies, guidelines and programs to effectively implement the purposes of the Center;\nb. To approve the annual and supplemental budgets of the Center;\nc. To fix any services or similar fees the Center may charge the end-users of its services;\nd. To promulgate rules as may be necessary for the effective exercise of the powers and functions of the Center;\ne. To authorize any contract or agreement as may be necessary for the proper, efficient and stable administration of the Center;\nf. To prepare and submit periodic and/or special reports to the President;\ng. To determine and approve the appointment of other officers of the Center, with their corresponding qualifications, duties and emoluments; and\nh. To appoint consultants and acknowledged experts in their respective fields as may be necessary for the realization of this Act."}},{"id":"PH-H5954-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Board of Governors; Composition, Term and Compensation. - The Center shall be governed and its activities and properties shall be managed by a Board of Governors which shall be chaired by the Secretary of Trade and Industry and ten (10) other Filipino citizens, five (5) of whom shall come from the government sector, namely: the secretaries of the National Economic and Development Authority, the Department of Foreign Affairs, the Department of Finance, the Department of Agriculture, and the Department of Environment and Natural Resources; and five (5) of whom shall come from the private sector whose functions shall be related to the purposes of the Center, all of whom shall be appointed by the President: Provided, That a representative from the private sector shall be appointed as Vice-chairman: Provided, further, That the ex-officio Vice-Chairman shall be the Director General: Provided, finally, that all board members shall have a broad experience in business, management or finance.\nThe term of office of the Board members from the government sector shall be for the duration of their public office while the term of office of the private sector Board members shall be three (3) years each until their successors shall have been appointed: Provided, that they shall be eligible for reappointment after the expiration of their respective terms.\nThe Board members shall meet regularly at least once a month and as often as the exigencies of the service demand. The presence of at least six (6) members shall constitute a quorum, and the vote of a majority of the members present shall be necessary for the adoption of any resolution, rule or decision.\nThe Board members shall receive for every meeting attended a per diem to be fixed by the President of the President."}},{"id":"PH-H5954-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Office of the Director General. -The chief operating officer and principal representative of the Center shall be the Director General assisted by a Deputy Director General, working full time, both to be appointed by the President: Provided, that such appointments shall be subject to confirmation by the Commission on Appointments."}},{"id":"PH-H5954-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Coordination with Government Agencies. - Government agencies concerned shall coordinate with the Center and are hereby obligated to give economic information and such other assistance for taxation purposes, as well as to act on the applications submitted by investors on any problem concerning the setting up of business in the Philippines. For this purpose, all government agencies concerned with business documentation and processing shall henceforth detail their appropriate representatives to the Center: Provided, That such government agencies shall provide for such detailed personnel's salaries and/or emoluments.\nMoreover, the Department of Foreign Affairs, through its commercial attaches worldwide, shall extend assistance to the Center by disseminating economic data properly released by the Center to the different countries concerned. The commercial attaches shall also furnish the Center with current and relevant economic data from other countries for circulation in the Philippines."}},{"id":"PH-H5954-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Vacancy Before Expiration of Term. - Any private sector Board member appointed by the President to fill a vacancy in the Board of Governors occurring prior to the expiration of the term for which his predecessor was appointed shall serve only for the unexpired portion of his predecessor."}},{"id":"PH-H5954-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Removal or Suspension for Cause. - An officer of the Center may be suspended or removed by the President for mismanagement, grave abuse of discretion, infidelity in the conduct of fiduciary relations, gross negligence in the performance of duties, dishonesty, corruption, or any act involving moral turpitude."}},{"id":"PH-H5954-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Appointment, Promotion, Terms and Conditions of Employment. -The officers and employees of the Center shall be covered by the Civil Service Law, as well as the rules of the Office of Compensation and Position Classification."}},{"id":"PH-H5954-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Location. -The Center's head office shall be located in a convenient and accessible site in the National Capital Region: Provided, That the regional offices of the Center may be integrated with the regional offices of the Department of Trade and Industry whenever feasible and shall obtain all its service functions under one roof, including the head office."}},{"id":"PH-H5954-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Appropriations. - An amount not exceeding fifteen million pesos (P15,000,000.00) to provide for the initial implementation of this Act shall be charged against the Contingent Fund. Thereafter, the amount necessary for the continued operation of the Center shall be included in the General Appropriations Act as part of the budget of the Department of Trade and Industry."}},{"id":"PH-H5954-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Implementing Guidelines. - The Department of Trade and Industry shall make all other necessary guidelines for the proper and effective implementation of this Act."}},{"id":"PH-H5954-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repealing Clause . - All other provisions of law contrary to or inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5954-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its complete publication in two (2) newspaper of general circulation.\nApproved, April 29, 1992."}}],"pack":"ph-p84"};
  FT["PH-H5955"] = {"id":"PH-H5955","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7471_1992.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act To Promote the Development of Philippine Overseas Shipping","orig":"An Act To Promote the Development of Philippine Overseas Shipping"},"level":"law","status":"active","topics":["trade"],"docNumber":"Republic Act No. 7471","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7471_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5955-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . - This Act shall be known and cited as the \"Philippine Overseas Shipping Development Act.\""}},{"id":"PH-H5955-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy . - It is hereby declared the policy of the Government of the Philippines to:\na. Develop and maintain a Philippine Merchant Marine composed of well-equipped, safe and modern vessels most suited for Philippines requirements and conditions, manned by qualified Filipino officers and crew, and owned and operated under the Philippine flag by citizens of the Philippines or by associations or corporations organized under the laws of the Philippines, at least sixty percent (60%) of the capital of which is owned by citizens of the Philippines;\nb. Assist in the development, recovery and expansion of Philippine overseas shipping capable of meeting the requirements of the expanding international trade of the Philippines;\nc. Provide assistance to Philippine shipping enterprises and encourage the long-range vessel acquisition, development, modernization and expansion through private investments without direct government financial assistance; and\nd. Create a healthy climate to attract private enterprises."}},{"id":"PH-H5955-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definitions. - As used in this Act:\na. \"Philippine overseas shipping\" means the transport of goods and/or passengers by a ship owned and operated under the Philippine flag by a Philippine shipping enterprise, except when the ship is operated solely between ports in the Philippines;\nb. \"Philippine shipping enterprise\" means a citizen of the Philippines or an association or corporation organized under the laws of the Philippines, at least sixty percent (60%) of the capital of which is owned by citizens of the Philippines and engaged exclusively in Philippine overseas shipping;\nc. \"MARINA\" means the Maritime Industry Authority;\nd. \"Monetary authority\" means the Central Bank of the Philippines and any other agency in charge of foreign exchange controls; and\ne. \"Regulations\" means the rules and regulations promulgated pursuant to Section 10 hereof"}},{"id":"PH-H5955-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Foreign Exchange Requirements. - Foreign exchange requirements of Philippine shipping enterprises for the purchase of oceangoing vessels for registration under the Philippine flag, for repair or improvement of vessels, for importation of engines, spare parts, accessories, supplies, containers and for other expenses required for the operation of vessels in foreign ports or in the high seas, when recommended by the MARINA, shall be made available to the Philippine shipping enterprise subject to the regulations."}},{"id":"PH-H5955-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Acquisition of Oceangoing Vessels. - Philippine shipping enterprises may likewise acquire oceangoing vessels for Philippine overseas shipping upon approval by the MARINA, subject to the guidelines prescribed in the regulations: Provided, That:\na. The funds utilized in the acquisition of the vessel are financed from sources other than the Philippine banking system;\nb. No guaranty of the monetary authority or of any Philippine government or private financial institution is granted or extended for the purpose;\nc. The vessel serves as sole collateral for the financing of the vessel and no other asset of the Philippine shipping enterprise is pledged, mortgaged, or used as security in case of default;\nd. All foreign exchange requirements for the servicing of the loan, the operation, maintenance and repair of the vessel, the purchase of supplies and related equipment shall be financed solely from earnings derived from the operation of the vessel and no foreign exchange shall be made available by the monetary authority and the Philippine banking system for these purposes;\ne. Mortgage documents and/or other financial agreements shall be filed with the monetary authority and such other government agencies in charge of such mortgage formalities; and\nf. Any excess foreign exchange earning shall be inwardly remitted and surrendered to the Philippine banking system."}},{"id":"PH-H5955-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Exemption from Import Duties and Taxes. - The importation by a Philippine shipping enterprise of oceangoing vessels for registration under the Philippine flag shall be exempt from the payment of import duties and taxes. The spare parts for the repair and/or overhaul of vessels shall likewise be exempt from the payment of import duties and taxes: Provided, That such items are destined or consigned either to:\na. A Philippine dry-docking or repair facility, accredited by the MARINA and registered as a customs-bonded warehouse, which will undertake the necessary repairs and works on the vessel; and\nb. The vessel in which the items are to be installed: Provided, That, if such items are found in locations other than the two (2) aforementioned ones or in places not authorized by customs, the person or entity in possession of such items shall be subject to full duties and taxes, including surcharges and penalties.\nLocal manufacturers or dealers who sell machinery, equipment, materials and spare parts to a Philippine shipping enterprise shall be entitled to tax credits for the full amount of import duties and taxes actually paid thereon, or on parts or components thereof, subject to the approval of the Secretary of Finance, upon the recommendation of the MARINA."}},{"id":"PH-H5955-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Exemption from Income Tax. - A Philippine shipping enterprise shall be exempt from payment of income tax on income derived from Philippine overseas shipping for a period of ten (10) years from the date of approval of this Act: Provided, That:\na. The entire net income, after deducting not more than ten percent (10%) thereof for distribution of profits or declaration of dividends, which would otherwise be taxable under the provisions of Title II of the National Internal Revenue Code, is reinvested for the construction, purchase, or acquisition of vessels and related equipment and/or in the improvement or modernization of its vessels and related equipment in accordance with the regulations; and\nb. The cumulative amount so reinvested shall not be withdrawn for a period of ten (10) years after the expiration of the period of income tax exemption or until the vessel or related equipment so acquired have been fully paid, whichever date comes earlier.\nAny amount not so invested or withdrawn prior to the expiration of the period stipulated herein shall be subject to the corresponding income tax, including penalties, surcharges and interests."}},{"id":"PH-H5955-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Registration and Deletion of Vessels. - All vessels owned by Philippine shipping enterprises and availing of the incentives under this Act shall be registered under the Philippine flag. Said vessels can only be deleted from the Philippine registry after the MARINA has determined that:\na. No other Philippine shipping enterprise is interested in acquiring the vessel; or\nb. The vessel has to be scrapped."}},{"id":"PH-H5955-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Requisition of Vessels. - The President of the Philippines may, in times of war and other national emergency, requisition, absolutely or temporarily, for any naval or military purpose, any and all vessels of Philippine registry. The Government shall pay the owner or operator of the vessel, based on normal conditions at the time of requisition:\na. The fair market value, if the vessel is taken absolutely; or\nb. The fair charter value, if the vessel is taken temporarily.\nIn case of disagreement, such fair value shall be determined by an arbitration committee composed of:\na. One (1) member to be appointed by the MARINA;\nb. One (1) member to be appointed by the owner or operator of the vessel; and\nc. One (1) member to be appointed by the two (2) members so appointed.\nThe decision of the arbitration committee shall be final and binding on both parties."}},{"id":"PH-H5955-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Rules and Regulations. - The MARINA, in consultation with the monetary authority and the Department of Finance, shall jointly formulate and promulgate the rules and regulation necessary for the implementation of this Act taking into consideration the policies and programs of the Government for the development of the Philippines overseas shipping."}},{"id":"PH-H5955-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Annual Report. - The MARINA, in coordination with the monetary authority and the Department of Finance, shall submit an annual report to the President of the Philippines and the Congress of the Philippines on the implementation of this Act, which report shall include:\na. The amount of foreign exchange earned, acquired and spent by Philippine shipping enterprises;\nb. The amount of income tax and import duties and taxes for which exemptions have been granted;\nc. The additional oceangoing vessels constructed, purchased or acquired; the improvements made thereon and the additional related equipment procured; and\nd. Such other information as the MARINA may deem necessary or the President of the Philippines may require."}},{"id":"PH-H5955-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Penal Provisions. - Violation of the provisions of this Act or the rules and regulations promulgated to implement the same shall be punished by a fine of not more than Ten thousand pesos (P 10,000) or imprisonment for not more than five (5) years, or both such fine and imprisonment, at the discretion of the court.\nIf the violation is committed by an association or corporation, the penalties prescribed hereunder shall be imposed on the president, the chief executive officer and the other officials and employees responsible for the violation.\nIf the violation is committed by a government official or employee, he shall, in addition to the penalties prescribed hereunder, be dismissed from the government service with all the administrative penalties accessory thereto."}},{"id":"PH-H5955-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repeating Clause. - All laws, executive orders, regulations, or parts thereof, inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H5955-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p84"};
  FT["PH-H5956"] = {"id":"PH-H5956","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7472_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"对第 7154 号共和国法的修改","en":"An Act Amending Section 1 of Republic Act No. 7154 Entitled \"An Act To Amend Section Fourteen of Batas Pambansa Bilang 129, Otherwise Known As the Judiciary Reorganization Act of 1981\" By Restoring the Regional Trial Court Branch in the Municipality of Candon and Creating Two Additional Regional Trial Court Branches in the Province of Ilocos Sur, and Providing Funds Therefor","orig":"An Act Amending Section 1 of Republic Act No. 7154 Entitled \"An Act To Amend Section Fourteen of Batas Pambansa Bilang 129, Otherwise Known As the Judiciary Reorganization Act of 1981\" By Restoring the Regional Trial Court Branch in the Municipality of Candon and Creating Two Additional Regional Trial Court Branches in the Province of Ilocos Sur, and Providing Funds Therefor"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 7472","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7472_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5956-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 14, paragraph (a), of Batas Pambansa Bilang 129, as amended, is hereby further amended to read as follows:\n\"(a) Seventy-two Regional Trial Judges shall commissioned for the First Judicial Region . There shall be:\n\"Three branches with seats thereat for the Province of Abra, with seats at Bangued and Bucay:\n\"Fourteen branches with seats thereat for the Province of Benguet and the City of Baguio, with seats at Baguio City, La Trinidad, and Buguias:\n\"Ten Branches with seats thereat for the Province of Ilocos Norte and the City of Laoag, with seats at Laoag City, Batac and Bangui;\n\"Eight branches with seats thereat for the Province of Ilocos Sur, with seats at Vigan, Narvacan, Candon, Cabugao and Tagudin:\nEleven branches with seats thereat for the Province of La Union, with seats at San Fernando, Agoo, Bauang, and Balaoan;\n\"Two branches with seats thereat for Mountain Province, with seats at Bontoc; and \"Twenty-four branches with seats thereat at the province of Pangasinan and the Cities of Dagupan and San Carlos, with seats at Lingayen, Dagupan City, Urdaneta, Villasis, Tayug, Rosales, Alaminos, Burgos, and San Carlos City.\""}},{"id":"PH-H5956-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, May 5, 1992."}}],"pack":"ph-p84"};
  FT["PH-H5957"] = {"id":"PH-H5957","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7473_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Lebak市","en":"An Act Establishing A High School in the Municipality of Lebak, Province of Sultan Kudarat, To Be Known As the Lebak High School, and Appropriating Funds Therefor","orig":"An Act Establishing A High School in the Municipality of Lebak, Province of Sultan Kudarat, To Be Known As the Lebak High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7473","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7473_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5957-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in the Poblacion, Municipality of Lebak, Province of Sultan Kudarat, to be known as the Lebak High School."}},{"id":"PH-H5957-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5957-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount needed to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5957-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5958"] = {"id":"PH-H5958","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7475_1992.html","fetchedAt":"2026-10-06","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"设立Roxas市","en":"An Act Establishing A Vocational and Technical High School in San Aquilino, Municipality of Roxas, Province of Oriental Mindoro, To Be Known As the Marcelo I. Cabrera Vocational High School, and Appropriating Funds Therefor","orig":"An Act Establishing A Vocational and Technical High School in San Aquilino, Municipality of Roxas, Province of Oriental Mindoro, To Be Known As the Marcelo I. Cabrera Vocational High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7475","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 1 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7475_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5958-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a vocational and technical high school in San Aquilino, Municipality of Roxas, Province of Oriental Mindoro, to be known as the Marcelo I. Cabrera Vocational High School.⚖ - ℒ&alpha;ɯ&rho;hi&#2551"}}],"pack":"ph-p84"};
  FT["PH-H5959"] = {"id":"PH-H5959","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7476_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Baler市","en":"An Act Establishing A High School in the Municipality of Baler, Province of Aurora, To Be Known As the Baler High School, and Appropriating Funds Therefor","orig":"An Act Establishing A High School in the Municipality of Baler, Province of Aurora, To Be Known As the Baler High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7476","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7476_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5959-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in the Municipality of Baler, Province of Aurora, to be known as the Baler High School."}},{"id":"PH-H5959-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5959-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5959-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5960"] = {"id":"PH-H5960","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7477_1992.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting the People's Broadcasting Service, Inc., A Franchise To Construct, Install, Operate and Maintain For Commercial Purposes Radio Broadcasting and Television Stations in the Philippines and For Other Purposes","orig":"An Act Granting the People's Broadcasting Service, Inc., A Franchise To Construct, Install, Operate and Maintain For Commercial Purposes Radio Broadcasting and Television Stations in the Philippines and For Other Purposes"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7477","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7477_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5960-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the People's Broadcasting Service, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio broadcasting and television stations in the Philippines with the corresponding technological auxiliaries or facilities, special broadcast and other program, distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H5960-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5960-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H5960-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language or speech, for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5960-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5960-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of approval of this Act unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5960-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H5960-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5960-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Democratization of Ownership . - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5960-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5960-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest in the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5960-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5960-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing Clause . - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5960-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5960-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p84"};
  FT["PH-H5961"] = {"id":"PH-H5961","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7478_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting the Sarraga Integrated Management Corporation of the Philippines A Franchise To Construct, Install, Operate and Maintain For Commercial Purposes Radio and Television Broadcasting Stations in the Philippines and For Other Purposes","orig":"An Act Granting the Sarraga Integrated Management Corporation of the Philippines A Franchise To Construct, Install, Operate and Maintain For Commercial Purposes Radio and Television Broadcasting Stations in the Philippines and For Other Purposes"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7478","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7478_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5961-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Sarraga Integrated Management Corporation of the Philippines, its successors or assigns and hereunder referred to as the grantee, a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio and television broadcasting station the Philippines, with the corresponding technological auxiliaries or facilities, special broadcast and other broadcast distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H5961-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established by law."}},{"id":"PH-H5961-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H5961-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide reasonable public service tune to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5961-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - The President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5961-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5961-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after approval or this Act. The grantee shall construct, complete and operate a television or radio station within two (2) years from the date of its acceptance in writing of this franchise. Refusal or failure to accept the franchise or to operate within the prescribed period shall render the franchise void."}},{"id":"PH-H5961-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provision. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code. The return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5961-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Democratization of Ownership. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5961-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5961-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with another corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5961-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5961-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealability and Non-exclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5961-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H5961-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5961-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p84"};
  FT["PH-H5962"] = {"id":"PH-H5962","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7479_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Naming the Airfield At the Sangley Point Naval and Air Training Station To Major Danilo Atienza Airfield, Sangley Point","orig":"An Act Naming the Airfield At the Sangley Point Naval and Air Training Station To Major Danilo Atienza Airfield, Sangley Point"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7479","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7479_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5962-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The airfield at the Sangley Point Naval and Air Training Station is hereby named as Major Danilo Atienza Airfield."}},{"id":"PH-H5962-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5963"] = {"id":"PH-H5963","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7480_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Pandami in the Province of Sulu To Municipality of Lapak, Amending For the Purpose Batas Pambansa Blg. 324","orig":"An Act Changing the Name of the Municipality of Pandami in the Province of Sulu To Municipality of Lapak, Amending For the Purpose Batas Pambansa Blg. 324"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7480","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7480_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5963-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Pandami in the Province of Sulu is hereby changed to Municipality of Lapak, amending for the purpose Section 1 of Batas Pambansa Blg. 324."}},{"id":"PH-H5963-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p84"};
  FT["PH-H5964"] = {"id":"PH-H5964","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7481_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Pilar市","en":"An Act Converting the Rural Health Unit in the Municipality of Pilar, Camotes Island, Province of Cebu, Into A Five-bed Capacity Health Infirmary, To Be Known As the Pilar Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Pilar, Camotes Island, Province of Cebu, Into A Five-bed Capacity Health Infirmary, To Be Known As the Pilar Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7481","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7481_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5964-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Pilar, Camotes Island, Province of Cebu, is hereby converted into a five-bed capacity health infirmary, to be known as the Pilar Health Infirmary."}},{"id":"PH-H5964-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5964-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
  FT["PH-H5965"] = {"id":"PH-H5965","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7482_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Barobo市","en":"An Act Converting the Rural Health Unit in the Municipality of Barobo, Province of Surigao Del Sur, Into A Five-bed Capacity Health Infirmary, To Be Known As the Barobo Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Barobo, Province of Surigao Del Sur, Into A Five-bed Capacity Health Infirmary, To Be Known As the Barobo Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7482","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7482_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5965-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Barobo, Province of Surigao del Sur, is hereby converted into a five-bed capacity health infirmary, to be known as the Barobo Health Infirmary."}},{"id":"PH-H5965-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5965-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p84"};
